query:
-- Delete all duplicate user rows keeping only the minimum id per openId
DELETE FROM users
WHERE openId IS NOT NULL
AND id NOT IN (
  SELECT min_id FROM (
    SELECT MIN(id) as min_id
    FROM users
    WHERE openId IS NOT NULL
    GROUP BY openId
  ) as canonical
);

-- Verify final counts
SELECT COUNT(*) as total_users FROM users;
SELECT COUNT(DISTINCT openId) as distinct_openids FROM users WHERE openId IS NOT NULL;
SELECT COUNT(*) as users_with_email FROM users WHERE email IS NOT NULL;

